import dilimanAor from '@/lib/diliman-aor.json';

export const DILIMAN_CENTER = {
  lat: 14.6530,
  lng: 121.0680,
};

export const DEFAULT_ZOOM = 15;

// Diliman AOR outline: the thesis scope, drawn as a dashed line on both maps.
// Generated by scripts/build-diliman-aor.mjs from OpenStreetMap; it matches
// the Diliman outline Google Maps shows.
export const DILIMAN_AOR_OUTLINE = dilimanAor as GeoJSON.Feature<GeoJSON.Polygon>;
export const AOR_OUTLINE_SOURCE = 'diliman-aor';
export const AOR_OUTLINE_LINE_LAYER = 'diliman-aor-line';
export const AOR_OUTLINE_DASH = [2.5, 2];

/**
 * A quiet guide line, not a border: thin and translucent, and a softer red
 * on the dark map, where saturated red glares.
 */
export function aorOutlineStyle(isDark: boolean) {
  return isDark ? { color: '#ff8a8a', opacity: 0.45 } : { color: '#e0353b', opacity: 0.55 };
}

/**
 * Phones: where the top controls (status filters, then the search bar under
 * them) end, measured from below the safe-area inset. Banners and toasts that
 * sit under those controls start from here. Keep in step with the mobile
 * layout in DashboardOverlay.
 */
export const MOBILE_TOP_CONTROLS_BOTTOM = '9.25rem';
